          "警告二（使用正确的操作系统）：这些资料里很多假设你在用 Mac 或 Linux 环境。如果你做了前面的安装课，应该已在双系统或虚拟机里装好 Linux，或者你在用 macOS；如果既没有 macOS 也没有任何官方 Ubuntu 风味版，请回到 Installations 那一课。",
          "第 1 项：访问 Software Carpentry Foundation 设计的 The Unix Shell 课程。那里有一整套 CLI 课程，但现在只需专注完成指定四节——Download files（只跟这一节的说明做，不需要安装任何软件，可直接进入下一条）、Introducing the Shell、Navigating Files and Directories、Working With Files and Directories。",
