      "why": "这是 Git 单元里真正动手的一课：在 GitHub 建一个专用练习仓库 git_test，克隆到本地，创建和修改文件、提交成快照，再推送回 GitHub。从今往后每个 TOP 项目都用这套流程保存和展示你的作品。这一串命令占日常 Git 使用量的 70–80%，官方说：掌握它们，你就已经走完掌握 Git 的一半以上路程。",
