            "先给所有 Odin 项目安一个统一的家。官方让你在 home 目录（主目录，用 ~ 表示）里创建 repos 目录并进入：mkdir repos 创建，cd repos/ 进入。官方提醒：不同操作系统的主目录路径有差异，~ 有时是 /Users/your_username（macOS），有时是 /home/your_username（Linux）；不确定自己是否在主目录时，输入 cd ~ 回去即可。",
