            "验证连接：cd git_test 进入刚下载的仓库目录，运行 git remote -v，应该看到类似下面的输出（USER-NAME 是你的 GitHub 用户名）：两行分别以 (fetch) 和 (push) 结尾，显示的都是你在 GitHub 创建的仓库地址——它就是你本地副本的远端（remote）。",
            "每行开头的 origin 是这个远端连接的名字。官方的说法很生动：origin 既是默认名也是远端仓库命名的惯例，但它完全可以叫 party-parrot 或者 dancing-banana。现在不用纠结 origin 的细节，本课末尾推送时它还会再出现。"
