            "这个设计的好处：你改了很多文件时，可以挑选其中一部分（git add 文件名）一起提交，其余的留到下次；git add . 则表示把当前目录及其全部子目录的改动都放进暂存区。后面要讲的“原子提交”最佳实践，正是建立在这个两步机制上。"
