            "为什么会有这种写法？历史原因。旧代码和不少老教程里会频繁出现自闭合写法，浏览器也都能正常渲染它们。但是：最新版 HTML 规范不鼓励这种写法，并视其为无效（invalid）。所以结论是——看到 <br /> 要认识它、知道它和 <br> 是一回事；自己写的时候按规范写 <br>、<img>，不要加那个斜杠。",
